import React, { useState, useEffect, useCallback } from 'react';
import { Card, Button, Input, Alert, api } from '../App';

const Label = ({ children }) => (
  <div style={{ fontSize: 11, fontWeight: 700, color: '#444', textTransform: 'uppercase', letterSpacing: 0.5, marginBottom: 6 }}>{children}</div>
);

const NumInput = ({ value, onChange, placeholder, width = 80 }) => (
  <input type="number" value={value || ''} onChange={e => onChange(e.target.value)} placeholder={placeholder || '0'}
    style={{ width, padding: '7px 10px', border: '1.5px solid #cbd5e0', borderRadius: 6, fontSize: 13 }} />
);

export default function MappingPage() {
  const [parties,       setParties]       = useState([]);
  const [allGardens,    setAllGardens]    = useState([]); // all marks from catalogue
  const [allGrades,     setAllGrades]     = useState([]);
  const [allBrokers,    setAllBrokers]    = useState([]);
  // grade → gardens mapping from catalogue
  const [gradeGardens,  setGradeGardens]  = useState({}); // {BOP: ['Halmari','Doomni'...]}

  const [selected,      setSelected]      = useState(null);
  const [search,        setSearch]        = useState('');
  const [saving,        setSaving]        = useState(false);
  const [alert,         setAlert]         = useState(null);
  const [addMode,       setAddMode]       = useState(false);
  const [newParty,      setNewParty]      = useState({ name: '', code: '' });
  const [importing,     setImporting]     = useState(false);
  const [importResult,  setImportResult]  = useState(null);

  // Party master state
  const [selectedGrades,  setSelectedGrades]  = useState([]);   // grades selected for this party
  const [mappedGardens,   setMappedGardens]   = useState([]);   // gardens mapped
  const [gradeSamples,    setGradeSamples]     = useState({});  // grade → max lots
  const [gradeRanges,     setGradeRanges]      = useState({});  // grade → {min, max}
  const [brokerList,      setBrokerList]       = useState([]);
  const [bagsFrom,        setBagsFrom]         = useState('');
  const [bagsTo,          setBagsTo]           = useState('');
  const [nwtFrom,         setNwtFrom]          = useState('');
  const [nwtTo,           setNwtTo]            = useState('');
  const [skipBlankLsp,    setSkipBlankLsp]     = useState(true);
  const [skipDupBGG,      setSkipDupBGG]       = useState(false);
  const [gSearch,         setGSearch]          = useState('');

  const load = useCallback(async () => {
    const [p, g, gr, br] = await Promise.all([
      api.get('/mapping/summary/all').catch(() => ({ data: [] })),
      api.get('/mapping/gardens').catch(() => ({ data: [] })),
      api.get('/marking/grades/list').catch(() => ({ data: [] })),
      api.get('/mapping/brokers-available').catch(() => ({ data: [] }))
    ]);
    setParties(p.data);
    setAllGardens(g.data);
    setAllGrades(gr.data);
    setAllBrokers(br.data);
  }, []);

  // Load grade→gardens mapping from catalogue
  const loadGradeGardens = useCallback(async () => {
    try {
      const r = await api.get('/mapping/grade-gardens');
      setGradeGardens(r.data || {});
    } catch (e) {}
  }, []);

  useEffect(() => { load(); loadGradeGardens(); }, [load, loadGradeGardens]);

  const selectParty = async (p) => {
    setSelected(p); setAlert(null);
    try {
      const r = await api.get(`/mapping/party-master/${p.id}`);
      const pm = r.data;
      setMappedGardens(pm.gardens || []);
      setGradeSamples(pm.grade_samples || {});
      setGradeRanges(pm.grade_ranges || {});
      setBrokerList(pm.broker_list || []);
      setBagsFrom(pm.bags_from || '');
      setBagsTo(pm.bags_to || '');
      setNwtFrom(pm.nwt_from || '');
      setNwtTo(pm.nwt_to || '');
      setSkipBlankLsp(pm.skip_blank_lsp !== false);
      setSkipDupBGG(pm.skip_dup_broker_garden_grade || false);
      // Detect which grades are being used from grade_samples
      const usedGrades = Object.keys(pm.grade_samples || {}).filter(g => pm.grade_samples[g] > 0);
      setSelectedGrades(usedGrades.length > 0 ? usedGrades : []);
    } catch (e) {
      setMappedGardens([]); setGradeSamples({}); setGradeRanges({});
      setBrokerList([]); setBagsFrom(''); setBagsTo(''); setNwtFrom(''); setNwtTo('');
      setSkipBlankLsp(true); setSkipDupBGG(false); setSelectedGrades([]);
    }
  };

  // When grades are selected, auto-populate gardens for those grades
  const toggleGrade = (grade) => {
    const newSel = selectedGrades.includes(grade)
      ? selectedGrades.filter(g => g !== grade)
      : [...selectedGrades, grade];
    setSelectedGrades(newSel);

    // Auto-add gardens for newly selected grades
    if (!selectedGrades.includes(grade)) {
      const gardensForGrade = gradeGardens[grade] || [];
      setMappedGardens(prev => {
        const combined = new Set([...prev, ...gardensForGrade]);
        return Array.from(combined);
      });
    } else {
      // Remove gardens that only belong to deselected grade (not in any other selected grade)
      const remaining = newSel.filter(g => g !== grade);
      const keepGardens = new Set();
      remaining.forEach(g => (gradeGardens[g] || []).forEach(garden => keepGardens.add(garden)));
      setMappedGardens(prev => prev.filter(g => keepGardens.has(g)));
    }
  };

  const toggleGarden = (g) => setMappedGardens(m => m.includes(g) ? m.filter(x => x !== g) : [...m, g]);
  const toggleBroker = (b) => setBrokerList(l => l.includes(b) ? l.filter(x => x !== b) : [...l, b]);

  const setGradeSample = (g, v) =>
    setGradeSamples(s => ({ ...s, [g]: v === '' ? 0 : parseInt(v) || 0 }));
  const setGradeRangeVal = (g, field, v) =>
    setGradeRanges(r => ({ ...r, [g]: { ...(r[g] || {}), [field]: v === '' ? 0 : parseFloat(v) || 0 } }));

  const saveAll = async () => {
    if (!selected) return;
    setSaving(true);
    try {
      await api.post('/mapping', {
        party_id:    selected.id,
        gardens:     mappedGardens,
        grade_samples: gradeSamples,
        grade_ranges:  gradeRanges,
        broker_list:   brokerList,
        bags_from:   bagsFrom  ? parseInt(bagsFrom)   : 0,
        bags_to:     bagsTo    ? parseInt(bagsTo)     : 0,
        nwt_from:    nwtFrom   ? parseFloat(nwtFrom)  : 0,
        nwt_to:      nwtTo     ? parseFloat(nwtTo)    : 0,
        skip_blank_lsp: skipBlankLsp,
        skip_dup_broker_garden_grade: skipDupBGG
      });
      setAlert({ msg: `✅ Party Master saved for ${selected.party_name}`, type: 'success' });
      load();
    } catch (e) {
      setAlert({ msg: '❌ ' + (e.response?.data?.error || e.message), type: 'error' });
    } finally { setSaving(false); }
  };

  const addParty = async () => {
    if (!newParty.name || !newParty.code) { setAlert({ msg: 'Name and code required', type: 'error' }); return; }
    try {
      await api.post('/parties', { party_name: newParty.name, party_code: newParty.code });
      setNewParty({ name: '', code: '' }); setAddMode(false); load();
    } catch (e) { setAlert({ msg: e.response?.data?.error || e.message, type: 'error' }); }
  };

  const delParty = async (id, name) => {
    if (!window.confirm(`Delete "${name}"?`)) return;
    await api.delete(`/parties/${id}`);
    setSelected(null); load();
  };

  const importParties = async (file) => {
    setImporting(true); setImportResult(null);
    const fd = new FormData(); fd.append('file', file);
    try { const r = await api.post('/mapping/import-parties', fd); setImportResult(r.data); load(); }
    catch (e) { setImportResult({ error: e.response?.data?.error || e.message }); }
    finally { setImporting(false); }
  };

  const filteredParties = parties.filter(p =>
    p.party_name.toLowerCase().includes(search.toLowerCase()) ||
    p.party_code.toLowerCase().includes(search.toLowerCase())
  );

  // Gardens filtered by search + currently selected grades
  const gardensInSelectedGrades = selectedGrades.length > 0
    ? [...new Set(selectedGrades.flatMap(g => gradeGardens[g] || []))]
    : allGardens;
  const filteredGardens = gardensInSelectedGrades.filter(g =>
    g.toLowerCase().includes(gSearch.toLowerCase())
  );

  const chipStyle = (sel, selBg = '#dbeafe', selBorder = '#1a3c5e', selText = '#1e40af') => ({
    padding: '4px 12px', borderRadius: 20, cursor: 'pointer', fontSize: 12, fontWeight: 600,
    border: `1.5px solid ${sel ? selBorder : '#e2e8f0'}`,
    background: sel ? selBg : '#f9fafb',
    color: sel ? selText : '#666',
    userSelect: 'none', transition: 'all 0.1s'
  });

  const activeGrades = selectedGrades.length > 0 ? selectedGrades : [];

  return (
    <div>
      <h2 style={{ marginBottom: 4, color: '#1a3c5e' }}>🔗 Party Master</h2>
      <p style={{ color: '#888', fontSize: 13, marginBottom: 16 }}>Configure grades, gardens, brokers and lot filters per party in one screen.</p>
      {alert && <Alert msg={alert.msg} type={alert.type} />}

      <div style={{ display: 'flex', gap: 16, alignItems: 'flex-start' }}>
        {/* ── LEFT: Party list ── */}
        <Card style={{ width: 270, minWidth: 250, flexShrink: 0, padding: 14 }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 10 }}>
            <h3 style={{ fontSize: 14 }}>Parties ({filteredParties.length})</h3>
            <div style={{ display: 'flex', gap: 5 }}>
              <Button size="sm" variant="outline" onClick={() => document.getElementById('pimport').click()} style={{ fontSize: 10, padding: '4px 7px' }}>
                {importing ? '…' : '📥'}
              </Button>
              <input id="pimport" type="file" accept=".xlsx,.xls" style={{ display: 'none' }}
                onChange={e => { if (e.target.files[0]) importParties(e.target.files[0]); e.target.value = ''; }} />
              <Button size="sm" onClick={() => setAddMode(!addMode)}>+ Add</Button>
            </div>
          </div>

          {importResult && (
            <div style={{ fontSize: 11, padding: '5px 8px', borderRadius: 5, marginBottom: 8,
              background: importResult.error ? '#fee2e2' : '#f0fdf4',
              color: importResult.error ? '#991b1b' : '#166534' }}>
              {importResult.error ? `❌ ${importResult.error}` : `✅ ${importResult.imported} imported`}
            </div>
          )}

          {addMode && (
            <div style={{ background: '#f0f8ff', padding: 10, borderRadius: 6, marginBottom: 10 }}>
              <Input label="Name" value={newParty.name} onChange={v => setNewParty(p => ({ ...p, name: v }))} placeholder="ASHA TEA" />
              <Input label="Code" value={newParty.code} onChange={v => setNewParty(p => ({ ...p, code: v.toUpperCase() }))} placeholder="AA" />
              <div style={{ display: 'flex', gap: 6 }}>
                <Button size="sm" variant="success" onClick={addParty}>Save</Button>
                <Button size="sm" variant="outline" onClick={() => setAddMode(false)}>Cancel</Button>
              </div>
            </div>
          )}

          <input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search…"
            style={{ width: '100%', padding: '6px 10px', border: '1.5px solid #e2e8f0', borderRadius: 6, fontSize: 12, marginBottom: 8 }} />

          <div style={{ maxHeight: 560, overflowY: 'auto' }}>
            {filteredParties.length === 0 && (
              <div style={{ color: '#aaa', fontSize: 12, padding: 10, textAlign: 'center' }}>
                {parties.length === 0 ? 'No parties. Import PC.xlsx or click + Add.' : 'No match.'}
              </div>
            )}
            {filteredParties.map(p => (
              <div key={p.id} onClick={() => selectParty(p)}
                style={{ padding: '6px 10px', borderRadius: 6, cursor: 'pointer', marginBottom: 2,
                  background: selected?.id === p.id ? '#dbeafe' : '#f9fafb',
                  border: `1.5px solid ${selected?.id === p.id ? '#93c5fd' : 'transparent'}`,
                  display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <div>
                  <span style={{ fontWeight: 700, fontSize: 12 }}>[{p.party_code}]</span>
                  <span style={{ fontSize: 12, marginLeft: 5 }}>{p.party_name}</span>
                  <div style={{ fontSize: 10, color: '#888' }}>{p.garden_count || 0} gardens</div>
                </div>
                <button onClick={e => { e.stopPropagation(); delParty(p.id, p.party_name); }}
                  style={{ background: 'none', border: 'none', cursor: 'pointer', color: '#ddd', fontSize: 12 }}>✕</button>
              </div>
            ))}
          </div>
        </Card>

        {/* ── RIGHT: Single page party master ── */}
        {!selected
          ? <Card style={{ flex: 1, textAlign: 'center', padding: 40, color: '#aaa' }}>Select a party to configure Party Master</Card>
          : (
            <div style={{ flex: 1, display: 'flex', flexDirection: 'column', gap: 14 }}>
              {/* Header */}
              <Card style={{ padding: '14px 18px' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <div>
                    <h3 style={{ fontSize: 16 }}>[{selected.party_code}] {selected.party_name}</h3>
                    <div style={{ fontSize: 12, color: '#888' }}>{mappedGardens.length} gardens · {activeGrades.length} active grades</div>
                  </div>
                  <Button variant="success" onClick={saveAll} disabled={saving}>{saving ? 'Saving…' : '💾 Save Party Master'}</Button>
                </div>
              </Card>

              {/* ── SECTION 1: Grades (first) ── */}
              <Card style={{ padding: 16 }}>
                <Label>1. Select Grades — (choosing a grade auto-loads its gardens below)</Label>
                <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', marginBottom: 10 }}>
                  {allGrades.map(g => (
                    <div key={g} onClick={() => toggleGrade(g)} style={chipStyle(selectedGrades.includes(g), '#dcfce7', '#1a7a4a', '#166534')}>
                      {selectedGrades.includes(g) ? '✓ ' : ''}{g}
                    </div>
                  ))}
                </div>
                {selectedGrades.length > 0 && (
                  <div style={{ fontSize: 11, color: '#888' }}>Selected: {selectedGrades.join(', ')}</div>
                )}
              </Card>

              {/* ── SECTION 2: Grades × Max Lots × Rate Range ── */}
              {selectedGrades.length > 0 && (
                <Card style={{ padding: 16 }}>
                  <Label>2. Max Lots & Rate Range per Grade</Label>
                  <div style={{ overflowX: 'auto' }}>
                    <table style={{ borderCollapse: 'collapse', fontSize: 13 }}>
                      <thead>
                        <tr style={{ background: '#f0f4f8' }}>
                          <th style={{ padding: '7px 14px', textAlign: 'left', fontWeight: 700, color: '#444' }}>Grade</th>
                          <th style={{ padding: '7px 14px', textAlign: 'center', fontWeight: 700, color: '#444' }}>Max Lots</th>
                          <th style={{ padding: '7px 14px', textAlign: 'center', fontWeight: 700, color: '#444' }}>Rate Min ₹</th>
                          <th style={{ padding: '7px 14px', textAlign: 'center', fontWeight: 700, color: '#444' }}>Rate Max ₹</th>
                        </tr>
                      </thead>
                      <tbody>
                        {selectedGrades.map((g, i) => (
                          <tr key={g} style={{ borderBottom: '1px solid #f0f4f8', background: i % 2 === 0 ? '#fff' : '#fafbfc' }}>
                            <td style={{ padding: '8px 14px' }}>
                              <span style={{ background: '#dbeafe', color: '#1e40af', padding: '2px 10px', borderRadius: 99, fontWeight: 700 }}>{g}</span>
                            </td>
                            <td style={{ padding: '8px 14px', textAlign: 'center' }}>
                              <input type="number" min="0" max="999"
                                value={gradeSamples[g] || ''}
                                onChange={e => setGradeSample(g, e.target.value)}
                                placeholder="0"
                                style={{ width: 70, padding: '5px 8px', textAlign: 'center',
                                  border: `1.5px solid ${gradeSamples[g] > 0 ? '#1a7a4a' : '#cbd5e0'}`,
                                  borderRadius: 6, fontSize: 13, fontWeight: gradeSamples[g] > 0 ? 700 : 400,
                                  color: gradeSamples[g] > 0 ? '#166534' : '#555' }} />
                            </td>
                            <td style={{ padding: '8px 14px', textAlign: 'center' }}>
                              <input type="number" min="0"
                                value={gradeRanges[g]?.min || ''}
                                onChange={e => setGradeRangeVal(g, 'min', e.target.value)}
                                placeholder="0"
                                style={{ width: 80, padding: '5px 8px', textAlign: 'center', border: '1.5px solid #cbd5e0', borderRadius: 6, fontSize: 13 }} />
                            </td>
                            <td style={{ padding: '8px 14px', textAlign: 'center' }}>
                              <input type="number" min="0"
                                value={gradeRanges[g]?.max || ''}
                                onChange={e => setGradeRangeVal(g, 'max', e.target.value)}
                                placeholder="0"
                                style={{ width: 80, padding: '5px 8px', textAlign: 'center', border: '1.5px solid #cbd5e0', borderRadius: 6, fontSize: 13 }} />
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </Card>
              )}

              {/* ── SECTION 3: Gardens (filtered by selected grades) ── */}
              <Card style={{ padding: 16 }}>
                <Label>3. Gardens — {selectedGrades.length > 0 ? `Showing gardens for: ${selectedGrades.join(', ')}` : 'All gardens (select grades above to filter)'}</Label>
                <div style={{ display: 'flex', gap: 8, marginBottom: 10, alignItems: 'center' }}>
                  <input value={gSearch} onChange={e => setGSearch(e.target.value)} placeholder="Search gardens…"
                    style={{ flex: 1, padding: '7px 10px', border: '1.5px solid #e2e8f0', borderRadius: 6, fontSize: 13 }} />
                  <Button size="sm" variant="outline" onClick={() => setMappedGardens([...filteredGardens])}>Select All</Button>
                  <Button size="sm" variant="outline" onClick={() => setMappedGardens([])}>Clear</Button>
                  <span style={{ fontSize: 12, color: '#888' }}>{mappedGardens.length} selected</span>
                </div>
                <div style={{ display: 'flex', gap: 7, flexWrap: 'wrap', maxHeight: 200, overflowY: 'auto' }}>
                  {filteredGardens.length === 0
                    ? <div style={{ color: '#aaa', fontSize: 13 }}>No gardens. Import Catalogue first.</div>
                    : filteredGardens.map(g => (
                      <div key={g} onClick={() => toggleGarden(g)} style={chipStyle(mappedGardens.includes(g), '#dcfce7', '#1a7a4a', '#166534')}>
                        {mappedGardens.includes(g) ? '✓ ' : ''}{g}
                      </div>
                    ))
                  }
                </div>
              </Card>

              {/* ── SECTION 4: Brokers ── */}
              <Card style={{ padding: 16 }}>
                <Label>4. Broker List (leave empty for All Brokers)</Label>
                <div style={{ display: 'flex', gap: 7, flexWrap: 'wrap' }}>
                  {allBrokers.map(b => (
                    <div key={b} onClick={() => toggleBroker(b)} style={chipStyle(brokerList.includes(b))}>
                      {brokerList.includes(b) ? '✓ ' : ''}{b}
                    </div>
                  ))}
                </div>
                {brokerList.length > 0 && (
                  <div style={{ fontSize: 11, color: '#1e40af', marginTop: 6 }}>Selected: {brokerList.join(', ')}</div>
                )}
              </Card>

              {/* ── SECTION 5: Bags, Net Wt, Skip options ── */}
              <Card style={{ padding: 16 }}>
                <Label>5. Lot Filters & Skip Options</Label>
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 20 }}>
                  <div>
                    <div style={{ fontSize: 12, fontWeight: 600, color: '#555', marginBottom: 6 }}>No. of Packages (Bags)</div>
                    <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
                      <NumInput value={bagsFrom} onChange={setBagsFrom} placeholder="From" />
                      <span style={{ color: '#888' }}>–</span>
                      <NumInput value={bagsTo}   onChange={setBagsTo}   placeholder="To" />
                    </div>
                  </div>
                  <div>
                    <div style={{ fontSize: 12, fontWeight: 600, color: '#555', marginBottom: 6 }}>Net Weight (kg)</div>
                    <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
                      <NumInput value={nwtFrom} onChange={setNwtFrom} placeholder="From" />
                      <span style={{ color: '#888' }}>–</span>
                      <NumInput value={nwtTo}   onChange={setNwtTo}   placeholder="To" />
                    </div>
                  </div>
                </div>

                <div style={{ marginTop: 16 }}>
                  <div style={{ fontSize: 12, fontWeight: 600, color: '#555', marginBottom: 8 }}>Skip Options</div>
                  <label style={{ display: 'flex', alignItems: 'center', gap: 8, fontSize: 13, cursor: 'pointer', marginBottom: 10 }}>
                    <input type="checkbox" checked={skipBlankLsp} onChange={e => setSkipBlankLsp(e.target.checked)} style={{ width: 16, height: 16 }} />
                    Want to skip lots when Last Sale Price is blank [Y/N]
                  </label>
                  <label style={{ display: 'flex', alignItems: 'center', gap: 8, fontSize: 13, cursor: 'pointer' }}>
                    <input type="checkbox" checked={skipDupBGG} onChange={e => setSkipDupBGG(e.target.checked)} style={{ width: 16, height: 16 }} />
                    Want to skip extra lots when Broker, Garden &amp; Grade is same [Y/N]
                  </label>
                </div>
              </Card>
            </div>
          )
        }
      </div>
    </div>
  );
}
